.project-author {
  font-size: 12px;
  color: var(--gray-500);
  margin-bottom: 12px;
}

.project-stats {
  display: flex;
  gap: 16px;
  font-size: 12px;
  color: var(--gray-400);
}

.project-stats span {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Plus Page */
.plus-hero {
  padding: 120px 0 60px;
  background: linear-gradient(135deg, var(--dark) 0%, #2a2a2a 100%);
  color: var(--white);
  text-align: center;
}

.plus-hero h1 {
  font-size: 48px;
  font-weight: 800;
  margin-bottom: 16px;
}

.plus-hero p {
  font-size: 20px;
  color: var(--gray-300);
  margin-bottom: 32px;
}

.pricing-toggle {
  display: inline-flex;
  background: rgba(255,255,255,0.1);
  border-radius: 30px;
  padding: 4px;
  margin-bottom: 40px;
}

.pricing-tab {
  padding: 12px 32px;
  border-radius: 26px;
  font-size: 15px;
  font-weight: 600;
  color: var(--gray-300);
  transition: all 0.3s;
}

.pricing-tab.active {
  background: var(--white);
  color: var(--dark);
}

.pricing-card {
  background: var(--white);
  border-radius: 20px;
  padding: 40px;
  max-width: 480px;
  margin: 0 auto;
  color: var(--dark);
  box-shadow: 0 20px 60px rgba(0,0,0,0.3);
}

.pricing-header {
  text-align: center;
  margin-bottom: 32px;
}

.pricing-price {
  font-size: 56px;
  font-weight: 800;
  color: var(--dark);
}

.pricing-price span {
  font-size: 20px;
  font-weight: 500;
  color: var(--gray-500);
}

.pricing-billed {
  color: var(--gray-500);
  font-size: 14px;
  margin-top: 4px;
}

.pricing-savings {
  display: inline-block;
  background: var(--teal);
  color: var(--white);
  padding: 6px 16px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 700;
  margin-top: 12px;
}

.pricing-credits {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--gray-100);
  padding: 12px;
  border-radius: 8px;
  margin-bottom: 24px;
  font-size: 14px;
  font-weight: 500;
}

.pricing-features {
  list-style: none;
  margin-bottom: 32px;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid var(--gray-200);
  font-size: 14px;
}

.pricing-features li:last-child {
  border-bottom: none;
}

.pricing-features i {
  color: var(--teal);
  font-size: 18px;
  margin-top: 2px;
}

.pricing-terms {
  font-size: 12px;
  color: var(--gray-400);
  text-align: center;
  margin-top: 16px;
}

/* Carousel */
.course-carousel {
  position: relative;
  overflow: hidden;
}

.course-carousel-track {
  display: flex;
  gap: 24px;
  transition: transform 0.5s ease;
}

.course-carousel-track .course-card {
  min-width: 280px;
  flex-shrink: 0;
}

.carousel-controls {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-bottom: 16px;
}

/* Credits Features */
.credits-section {
  background: var(--gray-100);
}

.credits-carousel {
  overflow: hidden;
}

.feature-card {
  background: var(--white);
  border-radius: 16px;
  padding: 32px;
  text-align: center;
  box-shadow: 0 4px 16px rgba(0,0,0,0.06);
}

.feature-card i {
  font-size: 48px;
  color: var(--primary);
  margin-bottom: 16px;
}

.feature-card h4 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
}

.feature-card p {
  font-size: 14px;
  color: var(--gray-500);
}

/* Certificates */
.certificates-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.cert-card {
  background: var(--gray-100);
  border-radius: 16px;
  padding: 24px;
  text-align: center;
}

.cert-card i {
  font-size: 40px;
  color: var(--primary);
  margin-bottom: 16px;
}

.cert-card h4 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 8px;
}

.cert-card p {
  font-size: 13px;
  color: var(--gray-500);
}

/* FAQ */
.faq-section {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 0;
  font-size: 16px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
}

.faq-question i {
  font-size: 20px;
  transition: transform 0.3s;
}

.faq-item.active .faq-question i {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 20px;
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.7;
}

/* Login Page */
.login-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--gray-100);
  padding: 24px;
}

.login-card {
  background: var(--white);
  border-radius: 20px;
  padding: 48px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.08);
}

.login-header {
  text-align: center;
  margin-bottom: 32px;
}

.login-header h1 {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 8px;
}

.login-header p {
  color: var(--gray-500);
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px;
  border-radius: 8px;
  font-size: 15px;
  font-weight: 600;
  border: 1px solid var(--gray-200);
  transition: all 0.2s;
}

.social-btn:hover {
  background: var(--gray-100);
}

.social-btn.facebook {
  background: #1877F2;
  color: var(--white);
  border-color: #1877F2;
}

.social-btn.apple {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

.divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
  color: var(--gray-400);
  font-size: 13px;
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 8px;
}

.form-group input {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  font-size: 15px;
  transition: border-color 0.2s;
}

.form-group input:focus {
  outline: none;
  border-color: var(--primary);
}

.password-input {
  position: relative;
}

.password-toggle {
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  cursor: pointer;
}

.forgot-link {
  display: block;
  text-align: right;
  font-size: 13px;
  color: var(--primary);
  margin-top: 8px;
}

.login-submit {
  width: 100%;
  padding: 14px;
  background: var(--primary);
  color: var(--white);
  font-size: 16px;
  font-weight: 600;
  border-radius: 8px;
  transition: background 0.2s;
}

.login-submit:hover {
  background: var(--primary-dark);
}

.login-footer {
  text-align: center;
  margin-top: 24px;
  font-size: 14px;
  color: var(--gray-500);
}

.login-footer a {
  color: var(--primary);
  font-weight: 600;
}

/* Comparison Table */
.comparison-table {
  width: 100%;
  border-collapse: collapse;
}

.comparison-table th,
.comparison-table td {
  padding: 16px;
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.comparison-table th {
  font-weight: 600;
  color: var(--gray-500);
  font-size: 13px;
  text-transform: uppercase;
}

.comparison-table td:last-child {
  text-align: center;
}

.check-icon {
  color: var(--teal);
  font-size: 20px;
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-content {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-stats {
    justify-content: center;
  }

  .value-props-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .projects-gallery {
    columns: 3;
  }

  .certificates-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .header-main {
    flex-wrap: wrap;
  }

  .search-box {
    display: none;
  }

  .hero-text h1 {
    font-size: 32px;
  }

  .section-title {
    font-size: 24px;
  }

  .course-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .courses-layout {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: static;
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
  }

  .filter-section {
    margin-bottom: 0;
  }

  .projects-gallery {
    columns: 2;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-accordion {
    display: none;
  }

  .plus-hero h1 {
    font-size: 36px;
  }

  .pricing-toggle {
    flex-direction: column;
    width: 100%;
    max-width: 280px;
  }

  .certificates-grid {
    grid-template-columns: 1fr;
  }

  .value-props-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 16px;
  }

  .course-grid {
    grid-template-columns: 1fr;
  }

  .projects-gallery {
    columns: 1;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .projects-controls {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* Mobile Footer Accordion */
.footer-accordion {
  display: none;
}

@media (max-width: 768px) {
  .footer-accordion {
    display: block;
  }

  .footer-col {
    border-bottom: 1px solid var(--gray-600);
    padding-bottom: 16px;
  }

  .footer-col h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .footer-col h4 i {
    transition: transform 0.3s;
  }

  .footer-col.active h4 i {
    transform: rotate(180deg);
  }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-col.active ul {
    max-height: 300px;
  }
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.course-card {
  animation: fadeIn 0.5s ease forwards;
}

.course-card:nth-child(2) { animation-delay: 0.1s; }
.course-card:nth-child(3) { animation-delay: 0.2s; }
.course-card:nth-child(4) { animation-delay: 0.3s; }
.course-card:nth-child(5) { animation-delay: 0.4s; }
